from 整节工具 import *
b='## 2. 振动坐标的矩阵元\n\n如另文《振动共振与费米共振》所述，简正坐标算符的矩阵元如下；使用无量纲振动坐标$q$与简正坐标$Q$的关系重写：\n\n'+math(r'q=(\lambda/\hbar^2)^{1/4}Q,\qquad q^2=(2\pi c\omega/\hbar)Q^2')
b+='非简并振动：\n\n'+eq('2.1')+'二重简并振动：\n\n'+eq('2.2')
b+='式(1.42)已考虑下列事项（也可能有误）。\n\n（1）对各个$l$值，$l=v,v-2,v-4,\\ldots,1$或$0,\\ldots,-(v-2),-v$，分别用下式求$q_{\\mathrm{deg},a}$和$q_{\\mathrm{deg},b}$的矩阵元：\n\n'
selected=[x for x in blocks if '\\langle v+1, l-1' in x]
b+=math(selected[0])
b+='对给定$v$，$l$可取$v+1$个值。每个$l$值均有：\n\n'
for x in blocks:
    if '\\langle v+1 | q_{\\mathrm{deg},a}' in x or '\\langle v-1 | q_{\\mathrm{deg},a}' in x: b+=math(x)
b+='式(2.2)已按$l$可取值数$v+1$加权。在吸收光谱或拉曼光谱强度中，两个自由度叠加，须乘2；但在和频张量矩阵元中，$q_{\\mathrm{deg},a}^2$和$q_{\\mathrm{deg},b}^2$属于不同张量分量，不能乘这个2。\n\n（2）不同$l$的能级分裂至多约$0.001\\ \\mathrm{cm}^{-1}$，在通常凝聚态体系中小于均匀线宽，因而在光谱上重叠。按$l$的$v+1$个值加权便得到式(1-42)。\n\n以上公式基于三项近似：（1）高频隔离使CH伸缩（严格说是以分子对称坐标表示的振动形）近乎独立于其他振动，简正坐标仅由CH伸缩坐标构成；（2）CH键周围在分子面内和面外保持同样的轴对称性，振动偶极矩与拉曼张量主轴均不偏离CH方向；（3）即使两或三个CH键从同一C伸出，每个CH键随键长变化的偶极矩及光散射张量变化仍相同。下面讨论检验这些近似局限的方法。先列G矩阵值，圆括号内为氘代物，方括号内为¹³C同位素取代物的值。\n\n'
add(262,b,[14,15],'Q129：原引用1.41/1.42在本文件无对应编号，可能指另版，不擅改为2.1/2.2。要点与本节矩阵元前因子不同，分别照录。作者“可能有误”的限定保留，不能将简并加权结果冒称无条件核验。')
b='### 原文采用的物理常数与G矩阵数值\n\n以下常数及等号均按底本保留。阿伏伽德罗常数为$6.0220\\times10^{23}$。\n\n'
for sym,molar,mass,inv,den in [('H','1.0078','1.673','5.977','H'),('D','2.0141','3.345','2.990','D'),('C','12.000','19.927','0.502','C'),('^{13}C','13.0034','21.593','0.463','H')]:
    b+=math(fr'm_{{{sym}}}={molar}\times10^{{-3}}\ \mathrm{{kg/mol}}={mass}\times10^{{-27}}\ \mathrm{{kg}},\quad1/m_{{{den}}}={inv}\times10^{{26}}\ \mathrm{{kg}}^{{-1}}')
for label,t in [('CH₃','2.3'),('CH₂（烷基）','2.4'),('CH₂（乙烯基）','2.5'),('CH','2.6')]: b+='**'+label+'**\n\n'+eq(t)
add(263,b,[15,16],'Q130：原常数表把摩尔质量与单原子质量直接用等号连接，按原记法保留；¹³C行的倒数质量下标原为H，候选¹³C未采用。各G数值、单位与同位素括号照录，不用当前常数重算替换。')
b='## 3. 近似的检验之一：振动频率及光谱强度\n\n### （1）相同力常数近似的检验\n\n这是振动带峰归属时的问题。F矩阵的对角元素可求为：\n\n'
for label,t in [('CH₃','3.1'),('CH₂（烷基）','3.2'),('CH₂（乙烯基）','3.3'),('CH','3.4')]: b+='**'+label+'**\n\n'+eq(t)
b+='水岛、岛内《赤外線吸収とラマン効果》的附录2列代表性基团频率，附录3列代表性力常数。CH伸缩波数为：−CH₃约2960、2870（亚甲基为2926、2853）；−CH₂−约2930、2850；−CH<约2890；−CH=为3040—3010；CH₂=为3095—3075及2985—2965；≡CH为3300；−CHO为2900—2700（通常两条）；芳香族CH约3030，单位均为$\\mathrm{cm}^{-1}$。\n\n力常数单位为$\\mathrm{md}/\\mathring A=10^2\\ \\mathrm{N/m}$。在$(\\mathrm{-CH_2-CH_2-})_n$中，$K_{\\mathrm{CH}}=4.2$、$F_{\\mathrm{H\\cdots H}}=0.244$；CH₄中分别为4.42和0.1；HCO₂⁻中$K_{\\mathrm{CH}}=3.46$；CH₃CO₂⁻中分别为4.564和0.032。至少历史上广用的Urey-Bradley-Shimanouti力场按经验取$k=0$、$F\\prime=-0.1F$。\n\\nR. G. Snyder, *J. Chem. Phys.* **47**, 1316 (1967) 分析一系列正烷烃与聚乙烯的振动光谱，并计算价力场。甲基$\\nu_{\\mathrm{sym}}=2870$、$\\nu_{\\mathrm{deg}}=2950$，亚甲基$\\nu_{a1}=2845$、$\\nu_{b1}=2915\\ \\mathrm{cm}^{-1}$。甲基力常数$K_{\\mathrm{CH}}=4.699\\pm0.003$、$F_{\\mathrm{H\\cdots H}}=0.032\\pm0.002$，亚甲基分别为$4.538\\pm0.003$和$0.019\\pm0.003$。若将CH键孤立处理、从相同频率求力常数，甲基分别为4.656、0.061，亚甲基为4.544、0.009。\n\n例如取$K_{\\mathrm{CH}}=4.6$、$F_{\\mathrm{H\\cdots H}}=0.03\\ \\mathrm{md}/\\mathring A$可得：\n\n| 基团 | 模式与波数（cm⁻¹） |\n|---|---|\n| CH₃ | sym 2839；deg 2933 |\n| CH₂（烷基） | a1 2871；b1 2933 |\n| CH（乙烯基，原记法） | a1 2853；deg 2952 |\n| CH | CH 2960 |\n\n总体与实测相当一致，但细节显示相同力常数近似的局限：（a）甲基简并伸缩与亚甲基反对称振动被算为相同频率；（b）甲基全对称与亚甲基对称伸缩的大小顺序倒置。\n\n'
add(264,b,[16,17],'Q130：原示例频率表乙烯基行写CH及νdeg，未按前文CH₂/b1改写；文献题名未由原文提供，不编补。')
b='### （2）为CH键赋予偶极矩导数并在CH、CH₂、CH₃间取同值的合理性\n\n溶液、粉末等分子各向同性取向样品中，红外吸收谱线强度正比于$|\\langle v+1,l-1|q_{\\mathrm{deg},a}|v,l\\rangle|^2$。由(1.10)—(1.14)、(1.41)、(1.42)，可在省略公共因子后求$v=1-0$跃迁强度：\n\n'
for label,t in [('CH','3.5'),('CH₂','3.6'),('CH₃','3.7')]: b+='**'+label+'**\n\n'+eq(t)
b+='顺便，对CH₂=CH：\n\n'+math(r'I_{\mathrm{CH}}/I_{b1}/I_{a1}\sim2G_{\mathrm{CH}}/3G_{b1}/G_{a1}\sim1.0/1.56/0.48')
b+='查阅红外数据手册可发现，符合这些相对强度的实例并不多。主要原因是这些公式只适用于各基团单独存在的分子。若两个以上基团共存，对称坐标会混合而构成简正坐标，光谱强度也随之混合。\n\n'
add(265,b,[17,18],'Q129：原引用1.41/1.42仍保留。强度比与要点给出的0.913等有差异，各局部结果照录，不代算统一。')
b='## 4. 近似的检验之二：拉曼光谱强度与退偏比\n\n可利用拉曼光谱的相对强度与退偏比检验拉曼张量近似。通常先用以下两个量：\n\n'+eq('4.1')
b+='使用线偏振激发光，在相对入射方向90°观察散射光时，与入射光平行、垂直的偏振强度分别为：\n\n'+eq('4.2').replace('\\propto','=')
b+='因此总散射强度正比于$45a^2+7\\gamma^2$。两偏振分量之比称退偏比，记为$\\rho$：\n\n'+eq('4.3')
b+='全对称模式的退偏比取0到1/3之间的值；非全对称模式$a=0$，退偏比恒为3/4。许多分子的全对称模式只有对角拉曼张量，此时：\n\n'+eq('4.4')+eq('4.5a')+eq('4.5b')
b+='由(4.5a)求振动带相对强度，由(4.5b)求退偏比。\n\n'
for label,lo,hi in [('CH',6,7),('CH₂：a1',8,9),('CH₂：b1',10,12),('CH₃：全对称',13,14),('CH₃：简并',15,17)]:
    b+='### '+label+'\n\n'
    # 取整个旧公式区间，包含无编号强度式，不省略。
    first=next(i for i,x in enumerate(blocks) if '\\tag{4.'+str(lo)+'}' in x)
    last=next(i for i,x in enumerate(blocks) if '\\tag{4.'+str(hi)+'}' in x)
    for x in blocks[first:last+1]: b+=math(x).replace('[12 +','[\\frac12 +')
b+='以上给出了本节近似下拉曼带的相对强度和退偏比。下面计算它们随$r$的变化并与实测比较。\n\n'
add(266,b,[18,19,20],'Q131：原4.1各向异性式、4.5b以及4.7/4.9/4.14的数值系数与标准不变量推导/所列数据并不全部吻合，保留各式。原称全对称退偏比0—1/3也照译，不能当作普遍上限；候选须重新按给定几何和归一化推导，未采用。旧译4.12把1/2写12，已恢复原分数。')
